(6785154, 1018991, 98022, '<td valign="top">Very nice abstract shape and lighting.</td>', 'Very nice abstract shape and lighting.', '2012-06-04 01:06:34.000000', NULL, 1),
(6785162, 1019200, 83901, '<td valign="top">very nice photo clean and simple!</td>', 'very nice photo clean and simple!', '2012-06-04 01:09:06.000000', NULL, 1),
(6785172, 1018986, 83901, '<td valign="top">Great shot!</td>', 'Great shot!', '2012-06-04 01:13:08.000000', NULL, 1),
(6785195, 1018893, 62249, '<td valign="top">This is fun to look at. Good tones, cool bubbles. Not voting in this challenge, but if I were, I''d give it an 8 or 9.</td>', 'This is fun to look at. Good tones, cool bubbles. Not voting in this challenge, but if I were, I''d give it an 8 or 9.', '2012-06-04 01:33:27.000000', NULL, 1),
(6785196, 1019200, 62249, '<td valign="top">Nice. I like the translucent quality of the smoke.</td>', 'Nice. I like the translucent quality of the smoke.', '2012-06-04 01:33:52.000000', NULL, 1),
(6785198, 1018072, 62249, '<td valign="top">I like it. Perhaps a tad dark in lower right corner, but a tough tonal range to work with. Quite interesting.</td>', 'I like it. Perhaps a tad dark in lower right corner, but a tough tonal range to work with. Quite interesting.', '2012-06-04 01:34:45.000000', NULL, 1),
(6785199, 1019133, 62249, '<td valign="top">Interesting, and fun to try to puzzle out what it is.</td>', 'Interesting, and fun to try to puzzle out what it is.', '2012-06-04 01:35:29.000000', NULL, 1),
(6785201, 1018386, 62249, '<td valign="top">Nicely geometric. Well composed.</td>', 'Nicely geometric. Well composed.', '2012-06-04 01:36:08.000000', NULL, 1),
(6785202, 1018856, 62249, '<td valign="top">Dramatic contrast. Interesting texture.</td>', 'Dramatic contrast. Interesting texture.', '2012-06-04 01:37:02.000000', NULL, 1),
(6785204, 1019085, 62249, '<td valign="top">Cool. This would be great as a poster-sized print.</td>', 'Cool. This would be great as a poster-sized print.', '2012-06-04 01:37:56.000000', NULL, 1),
(6785205, 1018321, 62249, '<td valign="top">Excellent concept and title.</td>', 'Excellent concept and title.', '2012-06-04 01:38:26.000000', NULL, 1),
(6785206, 1019180, 62249, '<td valign="top">Good use of DOF.</td>', 'Good use of DOF.', '2012-06-04 01:39:13.000000', NULL, 1),
(6785209, 1019095, 62249, '<td valign="top">Like the architectural geometry. Wish there were a tiny bit more detail visible in the shadow areas (and yes, my monitor is calibrated). Good subject for an abstract.</td>', 'Like the architectural geometry. Wish there were a tiny bit more detail visible in the shadow areas (and yes, my monitor is calibrated). Good subject for an abstract.', '2012-06-04 01:40:15.000000', NULL, 1),
(6785212, 1018297, 62249, '<td valign="top">Lovely. Like a fairy cocktail. Some color banding is visible in lighter area of table top, so not truly black and white.</td>', 'Lovely. Like a fairy cocktail. Some color banding is visible in lighter area of table top, so not truly black and white.', '2012-06-04 01:42:20.000000', NULL, 1),
(6785216, 1018578, 62249, '<td valign="top">Lovely shades of gray in the bubbles. I think I''d like this better as a horizontal crop, perhaps in a 16x9 aspect ratio.</td>', 'Lovely shades of gray in the bubbles. I think I''d like this better as a horizontal crop, perhaps in a 16x9 aspect ratio.', '2012-06-04 01:43:37.000000', NULL, 1),
(6785218, 1019153, 62249, '<td valign="top">Cool. Like the tonal range, the sharpness, and the composition. Well done.</td>', 'Cool. Like the tonal range, the sharpness, and the composition. Well done.', '2012-06-04 01:44:05.000000', NULL, 1),
(6785219, 1018486, 62249, '<td valign="top">Lovely. Evocative. Would make a nice print.</td>', 'Lovely. Evocative. Would make a nice print.', '2012-06-04 01:44:32.000000', NULL, 1),
(6785221, 1018986, 62249, '<td valign="top">Interesting. Seems like a greeting card.</td>', 'Interesting. Seems like a greeting card.', '2012-06-04 01:45:18.000000', NULL, 1),
(6785223, 1018377, 62249, '<td valign="top">I enjoy shots like this that show the interplay of blinds and light.</td>', 'I enjoy shots like this that show the interplay of blinds and light.', '2012-06-04 01:46:23.000000', NULL, 1),
(6785227, 1019103, 62249, '<td valign="top">Nicely lit.</td>', 'Nicely lit.', '2012-06-04 01:47:07.000000', NULL, 1),
(6785229, 1019071, 62249, '<td valign="top">Nice. Good repetition of pattern.</td>', 'Nice. Good repetition of pattern.', '2012-06-04 01:47:40.000000', NULL, 1),
(6785230, 1017810, 62249, '<td valign="top">Lovely. Border really enhances the image, and I like the graininess. A good capture of a daily scene, yet you managed to infuse it with some mystery and intrigue.</td>', 'Lovely. Border really enhances the image, and I like the graininess. A good capture of a daily scene, yet you managed to infuse it with some mystery and intrigue.', '2012-06-04 01:49:35.000000', NULL, 1),
(6785233, 1018985, 62249, '<td valign="top">Great title and an image that''s fun to look at.</td>', 'Great title and an image that''s fun to look at.', '2012-06-04 01:50:56.000000', NULL, 1),
(6785236, 1018850, 62249, '<td valign="top">This shot has potential. I think I''d like it even more if it were either blurrier/grainer, or sharper. It hits an in-between spot that''s neither here nor there. But the composition and lighting are quite interesting, and I find myself spending a longer time than usual examining the image.</td>', 'This shot has potential. I think I''d like it even more if it were either blurrier/grainer, or sharper. It hits an in-between spot that''s neither here nor there. But the composition and lighting are quite interesting, and I find myself spending a longer time than usual examining the image.', '2012-06-04 01:54:20.000000', NULL, 1),
(6785237, 1019059, 62249, '<td valign="top">Nice. Moody.</td>', 'Nice. Moody.', '2012-06-04 01:54:45.000000', NULL, 1),
(6785238, 1019132, 62249, '<td valign="top">I like your minimalist approach.</td>', 'I like your minimalist approach.', '2012-06-04 01:55:49.000000', NULL, 1),
