(6785245, 1017874, 62249, '<td valign="top">Excellent image and title. Looking forward to reading your comments about this shot. Hope this places in top 10.</td>', 'Excellent image and title. Looking forward to reading your comments about this shot. Hope this places in top 10.', '2012-06-04 02:02:44.000000', NULL, 1),
(6785248, 1018537, 62249, '<td valign="top">This works well in b/w. Like the curved horizon and the tonality in the clouds. Good tonal range. Strikes a good balance between abstract and familiar.</td>', 'This works well in b/w. Like the curved horizon and the tonality in the clouds. Good tonal range. Strikes a good balance between abstract and familiar.', '2012-06-04 02:04:07.000000', NULL, 1),
