(6789061, 1017874, 112739, '<td valign="top">Utterly superb. The unheard screams of millions in an off beat harmony that only make sense when one takes a longer view.</td>', 'Utterly superb. The unheard screams of millions in an off beat harmony that only make sense when one takes a longer view.', '2012-06-07 15:17:57.000000', NULL, 1),
(6789065, 1018988, 112739, '<td valign="top">The soft aspect of the image is very well done. The bold black border may take away from that feeling.</td>', 'The soft aspect of the image is very well done. The bold black border may take away from that feeling.', '2012-06-07 15:20:51.000000', NULL, 1),
(6789067, 1019065, 112739, '<td valign="top">Interesting how the eye travels from place to place. Identifying the in focus area''s and then falling back to the not so in focus area''s. But they all need one another to make a completeness. Love the textures, lines, and tones.</td>', 'Interesting how the eye travels from place to place. Identifying the in focus area''s and then falling back to the not so in focus area''s. But they all need one another to make a completeness. Love the textures, lines, and tones.', '2012-06-07 15:22:52.000000', NULL, 1),
